/** @jsxImportSource react */

import { cn } from '@videojs/utils/style';
import type { ComponentProps, ReactNode } from 'react';

import { ErrorDialog } from '../shared/components/dialogs/error-dialog';
import { Poster } from '../shared/components/display/poster';
import { Title } from '../shared/components/display/title';
import { Container } from '../shared/components/layout/container';
import { LiveVideoGestures } from '../shared/skins/shared/live-video/behaviors/gestures';
import { LiveVideoHotkeys } from '../shared/skins/shared/live-video/behaviors/hotkeys';
import { BufferingIndicator } from './components/display/buffering-indicator';
import { DefaultLiveVideoControls } from './layout/controls';
import { LiveVideoStatusIndicators } from './skins/shared/live-video/display/status-indicators';

export interface LiveVideoSkinProps extends Omit<NonNullable<ComponentProps<typeof Container>>, 'children'> {
  children?: ReactNode;
  renderPoster?: NonNullable<ComponentProps<typeof Poster>>['renderImage'];
}

export function LiveVideoSkin({ children, className, renderPoster, ...props }: LiveVideoSkinProps = {}) {
  return (
    <Container className={cn('video-skin', className)} data-theme="default" data-preset="live-video" {...props}>
      {children}
      <Poster renderImage={renderPoster} />
      <BufferingIndicator />
      <ErrorDialog />
      <Title />
      <DefaultLiveVideoControls />
      <LiveVideoHotkeys />
      <LiveVideoGestures />
      <LiveVideoStatusIndicators />
    </Container>
  );
}
